WITH customer_totals AS (SELECT customer_id, COUNT(DISTINCT shipping_fee) AS unique_stores, SUM(CASE WHEN channel = 'mobile' THEN amount ELSE 0 END) AS mobile_amount FROM orders WHERE amount IS NOT NULL GROUP BY customer_id) SELECT c.id, c.city, ct.unique_stores, ct.mobile_amount FROM customers c LEFT OUTER JOIN customer_totals ct ON c.id = ct.customer_id WHERE ct.mobile_amount > 24 ORDER BY c.city ASC;
